/**
 * The view of a to-do: the row's `view` on GET /api/v1/todos and GET /api/v1/todos/{id}. The manager works it out
 * from the to-do, its runs' sessions, its asks and the time, so every client draws the same row without rules of its
 * own (proposal 6.1, 6.3). A row without it comes from an older manager and is drawn as before; so is a row whose
 * section or reason the client does not know.
 */
@Serializable
data class TodoSummary(
    val phase: TodoPhase = TodoPhase.Unknown(""),
    val section: TodoListSection = TodoListSection.Unknown(""),
    val reason: TodoReason = TodoReason.Unknown(""),
    /**
     * Line 2 of the row; absent when there is nothing to say (a plain To do row).
     */
    val line: TodoLine? = null,
    /**
     * When the reason began (the ask, the failure, the park, the close…); absent when nothing says.
     */
    val since: String? = null,
    /**
     * The next moment time alone changes this view (24 hours in Just finished, 48 hours to the Inactive mark, a
     * Someday date): a client files the row again then, without the hub. Absent when only new facts change it.
     */
    @SerialName("next_change_at") val nextChangeAt: String? = null,
    /**
     * The row's place in its section among the rows of its list, 0 first (proposal 3.4 "Within a section").
     */
    val rank: Int = 0,
    /**
     * The owner looked at it since it got where it is (docs/assistant/todo-status-sop.md "Seen"). Written only when
     * true.
     */
    val seen: Boolean? = null,
    /**
     * The Inactive mark: when activity stopped, on a task nothing has moved for 48 hours that no other rule places.
     * Absent while it is active.
     */
    val inactive: String? = null,
    /**
     * In Can wait: it needs the owner but can wait, and is not counted. Written only when true.
     */
    @SerialName("can_wait") val canWait: Boolean? = null,
    /**
     * The asks that hold the row in Needs you or Can wait, the most urgent first; absent when none does.
     */
    val asks: List<OwnerAsk>? = null,
    /**
     * Its steps; absent when it has none.
     */
    val steps: TodoStepCount? = null,
)

/**
 * What kind of place a To-dos place is (proposal 3.3): all (All To-dos), today, upcoming, or a project's. Open: a
 * newer hub may send other values.
 */
object TodoPlaceKind {
    const val ALL_VALUE = "all"
    const val TODAY = "today"
    const val UPCOMING = "upcoming"
    const val PROJECT = "project"
    val ALL = listOf("all", "today", "upcoming", "project")
}

/**
 * One place of the To-dos sidebar: All To-dos, Today, Upcoming, or a knowledge-base project with open to-dos.
 */
@Serializable
data class TodoPlace(
    /**
     * all, today, upcoming, or project:<slug>.
     */
    val id: String = "",
    val kind: String = "",
    /**
     * The project's title; "" for all, today and upcoming, which each client names in its own language.
     */
    val title: String = "",
    /**
     * The project's slug; only on a project's place.
     */
    val project: String? = null,
    /**
     * The place's part of TodoCounts.needs_you, counted the same way; 0 for today and upcoming, which draw no count.
     */
    @SerialName("needs_you") val needsYou: Int = 0,
    /**
     * The manager the place belongs to, stamped by the hub when it merges several managers' places; absent in a
     * manager's own answer.
     */
    val manager: String? = null,
)

/**
 * The numbers of the To-dos list (proposal 3.7), on GET /api/v1/todos and GET /api/v1/todos/places. Across managers
 * the hub adds them up field by field and key by key.
 */
@Serializable
data class TodoCounts(
    /**
     * Open to-dos except Someday: every to-do that is not closed (a start that failed counts), in any section but
     * Someday.
     */
    val open: Int = 0,
    /**
     * N: the to-dos in the Needs you section, each once however many of its runs ask; Can wait and quiet tasks are
     * not counted. For the To-dos V1 design's To-dos row badge, the bar's Needs you and the Needs you header. Of the
     * clients only iOS reads it, behind the V1 gate that is off in release builds; the release clients count their
     * To-dos row by rules of their own.
     */
    @SerialName("needs_you") val needsYou: Int = 0,
    /**
     * The rows of Working and Waiting; Just finished is listed at the foot of In progress but not counted.
     */
    @SerialName("in_progress") val inProgress: Int = 0,
    /**
     * Rows per section, every section named, 0 included, so the bytes stay stable and the hub adds maps up key by
     * key. Quiet tasks count here as the rows they are.
     */
    val sections: TodoCountsSections = TodoCountsSections(),
)

/**
 * The answer of GET /api/v1/todos/places: the places, and the counts of the whole list.
 */
@Serializable
data class TodoPlaces(
    /**
     * all, today and upcoming, then one place for each project with open to-dos, by slug.
     */
    val places: List<TodoPlace> = emptyList(),
    /**
     * The counts of All To-dos, as GET /api/v1/todos answers them.
     */
    val counts: TodoCounts = TodoCounts(),
)

/**
 * Where an owner's message to the to-do stands (proposal 3.6 "Message states"): sending, the device has not handed it
 * over yet; processing, the hub has it; delivered, its run or Persona took it; queued, it waits for its run's current
 * step to end; not_delivered, it was refused with nothing typed; unknown, nobody can say whether it arrived. A
 * timeline read from today's stores says only delivered, since a message is kept there only once its run took it.
 * Open: a newer hub may send other values.
 */
object TodoMessageState {
    const val SENDING = "sending"
    const val PROCESSING = "processing"
    const val DELIVERED = "delivered"
    const val QUEUED = "queued"
    const val NOT_DELIVERED = "not_delivered"
    const val UNKNOWN = "unknown"
    val ALL = listOf("sending", "processing", "delivered", "queued", "not_delivered", "unknown")
}

/**
 * What an entry of a to-do's conversation records (spec/fixtures/todo-rounds/README.md "Entries" says what each is
 * read from): instruction, the owner's words to the to-do; answer, an answer or a decision of the owner's; relay,
 * words Persona or the hub passed on to a run; run, one run's turns in a round, in one line; run_started, run_ended
 * and run_failed, a run put on the to-do, let go of, or not started; interrupted, a run whose latest turn in the
 * round was cut off; ask, a question for the owner; decision, a call Persona, a run or the hub made; result, what the
 * work came to; closed, the to-do was closed; scope, its scope changed; review, parked, report and overdue,
 * supervision nobody asked for. Closed: a client decodes a value a newer hub sends as unknown, counts it and skips
 * the entry. A value this app does not know decodes to Unknown with the raw value, and encodes back as it came.
 */
@Serializable(with = TodoEntryTypeSerializer::class)
sealed interface TodoEntryType {
    val raw: String

    data object Instruction : TodoEntryType { override val raw: String = "instruction" }
    data object Answer : TodoEntryType { override val raw: String = "answer" }
    data object Relay : TodoEntryType { override val raw: String = "relay" }
    data object Run : TodoEntryType { override val raw: String = "run" }
    data object RunStarted : TodoEntryType { override val raw: String = "run_started" }
    data object RunEnded : TodoEntryType { override val raw: String = "run_ended" }
    data object RunFailed : TodoEntryType { override val raw: String = "run_failed" }
    data object Interrupted : TodoEntryType { override val raw: String = "interrupted" }
    data object Ask : TodoEntryType { override val raw: String = "ask" }
    data object Decision : TodoEntryType { override val raw: String = "decision" }
    data object Result : TodoEntryType { override val raw: String = "result" }
    data object Closed : TodoEntryType { override val raw: String = "closed" }
    data object Scope : TodoEntryType { override val raw: String = "scope" }
    data object Review : TodoEntryType { override val raw: String = "review" }
    data object Parked : TodoEntryType { override val raw: String = "parked" }
    data object Report : TodoEntryType { override val raw: String = "report" }
    data object Overdue : TodoEntryType { override val raw: String = "overdue" }

    /** A value this app does not know, kept as it came. */
    data class Unknown(override val raw: String) : TodoEntryType

    companion object {
        val ALL: List<TodoEntryType> = listOf(TodoEntryType.Instruction, TodoEntryType.Answer, TodoEntryType.Relay, TodoEntryType.Run, TodoEntryType.RunStarted, TodoEntryType.RunEnded, TodoEntryType.RunFailed, TodoEntryType.Interrupted, TodoEntryType.Ask, TodoEntryType.Decision, TodoEntryType.Result, TodoEntryType.Closed, TodoEntryType.Scope, TodoEntryType.Review, TodoEntryType.Parked, TodoEntryType.Report, TodoEntryType.Overdue)

        fun of(raw: String): TodoEntryType = when (raw) {
            "instruction" -> TodoEntryType.Instruction
            "answer" -> TodoEntryType.Answer
            "relay" -> TodoEntryType.Relay
            "run" -> TodoEntryType.Run
            "run_started" -> TodoEntryType.RunStarted
            "run_ended" -> TodoEntryType.RunEnded
            "run_failed" -> TodoEntryType.RunFailed
            "interrupted" -> TodoEntryType.Interrupted
            "ask" -> TodoEntryType.Ask
            "decision" -> TodoEntryType.Decision
            "result" -> TodoEntryType.Result
            "closed" -> TodoEntryType.Closed
            "scope" -> TodoEntryType.Scope
            "review" -> TodoEntryType.Review
            "parked" -> TodoEntryType.Parked
            "report" -> TodoEntryType.Report
            "overdue" -> TodoEntryType.Overdue
            else -> TodoEntryType.Unknown(raw)
        }
    }
}

object TodoEntryTypeSerializer : KSerializer<TodoEntryType> {
    override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor("persona.core.contracts.generated.TodoEntryType", PrimitiveKind.STRING)

    override fun deserialize(decoder: Decoder): TodoEntryType {
        val raw = decoder.decodeString()
        val value = TodoEntryType.of(raw)
        if (value is TodoEntryType.Unknown) TodoViewWireDefects.unknownEnum?.invoke("TodoEntryType", raw)
        return value
    }

    override fun serialize(encoder: Encoder, value: TodoEntryType) {
        encoder.encodeString(value.raw)
    }
}

/**
 * Who an entry is by: owner; persona, Persona (the conversation that supervises the to-do included); lead, a Pinned
 * direction's lead; run, one of the to-do's Agent sessions; hub, the hub itself (its done judge included); extension.
 * Open: a newer hub may send other values.
 */
object TodoActorKind {
    const val OWNER = "owner"
    const val PERSONA = "persona"
    const val LEAD = "lead"
    const val RUN = "run"
    const val HUB = "hub"
    const val EXTENSION = "extension"
    val ALL = listOf("owner", "persona", "lead", "run", "hub", "extension")
}

/**
 * Who an entry is by; never a runtime, engine, model or folder.
 */
@Serializable
data class TodoActor(
    val kind: String = "",
    /**
     * The run, when kind is run and the hub knows which one.
     */
    val run: TodoRunRef? = null,
)

/**
 * How an owner's answer, or a call made in their place, came in: app, a To-dos screen; card, a card one of its runs
 * put up (a question, a plan, an approval); push, a notification's action; chat, said in a conversation; thread, a
 * reply in the to-do's chat topic; briefing, a briefing's card; default, Persona took the recommendation at its
 * deadline. Open: a newer hub may send other values.
 */
object TodoEntryVia {
    const val APP = "app"
    const val CARD = "card"
    const val PUSH = "push"
    const val CHAT = "chat"
    const val THREAD = "thread"
    const val BRIEFING = "briefing"
    const val DEFAULT = "default"
    val ALL = listOf("app", "card", "push", "chat", "thread", "briefing", "default")
}

/**
 * One thing that happened on a to-do: what someone said or did, or what the hub saw happen (proposal 3.6, 6.1
 * Activity). Clients draw it; they work out nothing from it.
 */
@Serializable
data class TodoTimelineEntry(
    /**
     * Unique within the to-do's timeline, and the same on every read while the hub keeps what it was read from.
     * Opaque to clients (spec/fixtures/todo-rounds/README.md says how the hub forms it).
     */
    val id: String = "",
    val type: TodoEntryType = TodoEntryType.Unknown(""),
    /**
     * When it happened; a run line's latest turn, or since when the run works for a live line that has no turn yet.
     */
    val at: String = "",
    val actor: TodoActor = TodoActor(),
    /**
     * Words someone wrote, as they wrote them: the owner's instruction or answer, a relay, a run's latest summary or
     * what it does now, a decision's choice, a report, a review's note; absent when nobody wrote any. Today's stores
     * keep a few of the hub's own sentences in the place of such words, in the language they were written in
     * (spec/fixtures/todo-rounds/README.md "Judgement calls"): a failed start's that names no error, a turn's that
     * ended without a summary, a permission or plan card's answer.
     */
    val text: String? = null,
    /**
     * The option the owner chose, on an answer whose text is what they said in a conversation rather than the option
     * itself; absent otherwise.
     */
    val choice: String? = null,
    /**
     * What an answer or a decision answers, in the words it was asked in; absent when nothing says.
     */
    val question: String? = null,
    /**
     * Why, in the words of whoever answered or decided; absent when nobody said.
     */
    val reason: String? = null,
    /**
     * What the hub says about it, as a key and its arguments (spec/fixtures/todo-rounds/README.md "Line keys");
     * absent when text says it all.
     */
    val line: TodoLine? = null,
    /**
     * The run it is about: the run a message or a relay reached, a run line's run, the run that started, ended or
     * failed; absent when the hub does not know which (a run line without one is "A run").
     */
    val run: TodoRunRef? = null,
    /**
     * The id of the to-do's open ask this is (an OwnerAsk id of its view); absent once that ask is no longer open.
     */
    val ask: String? = null,
    val via: String? = null,
    /**
     * Where the owner's instruction stands; only on instructions.
     */
    val state: String? = null,
    /**
     * The id of the to-do's decision it was read from (GET /api/v1/todos/{id}/decisions).
     */
    val decision: String? = null,
    /**
     * The decision that replaced it, on an entry read from a decision a later one superseded; absent while it holds.
     */
    @SerialName("superseded_by") val supersededBy: String? = null,
    /**
     * How many of its run's turns in the round the line stands for; on run and interrupted lines, absent on a live
     * line before its first turn ends.
     */
    val turns: Int? = null,
    /**
     * The run works now: only on a run line of the latest round. Written only when true.
     */
    val live: Boolean? = null,
)

/**
 * What a round of a to-do's conversation is (proposal 3.6): owner, one instruction or answer of the owner's and what
 * followed it; start, what came before the owner's first, headed by the request that started the work when the owner
 * made it; background, one day's supervision nobody asked for, drawn folded. Open: a newer hub may send other values.
 */
object TodoRoundKind {
    const val OWNER = "owner"
    const val START = "start"
    const val BACKGROUND = "background"
    val ALL = listOf("owner", "start", "background")
}

/**
 * One round of a to-do's conversation: a header and what followed it, as the hub groups them
 * (spec/fixtures/todo-rounds/README.md "Rounds"); clients only draw it.
 */
@Serializable
data class TodoRound(
    /**
     * Unique within the timeline and stable while the hub keeps what it was read from; opaque to clients.
     */
    val id: String = "",
    val kind: String = "",
    /**
     * When it began: its header's time, else its first entry's.
     */
    val at: String = "",
    /**
     * The owner's instruction or answer that opened it, or, on a start round, the owner's request that started the
     * work; absent on a start round the owner did not start and on a background round.
     */
    val header: TodoTimelineEntry? = null,
    /**
     * What followed, oldest first; the header is not repeated, and a round may have only its header.
     */
    val entries: List<TodoTimelineEntry> = emptyList(),
)

/**
 * A to-do's conversation: its rounds, oldest first, the latest at the bottom (proposal 3.6).
 */
@Serializable
data class TodoTimeline(
    /**
     * The rounds, oldest first.
     */
    val rounds: List<TodoRound> = emptyList(),
    /**
     * Earlier rounds exist than the ones listed. Written only when true.
     */
    val more: Boolean? = null,
)

/**
 * What kind of thing a to-do's work produced (proposal 6.1 Deliverable): booking, doc, file, link, change (a code
 * change), deploy (the work went live), report (what the work came to, in words). Today's hub sends change, deploy
 * and report. Open: a newer hub may send other values.
 */
object TodoResultKind {
    const val BOOKING = "booking"
    const val DOC = "doc"
    const val FILE = "file"
    const val LINK = "link"
    const val CHANGE = "change"
    const val DEPLOY = "deploy"
    const val REPORT = "report"
    val ALL = listOf("booking", "doc", "file", "link", "change", "deploy", "report")
}

/**
 * How a code change stands as the hub last saw it: open, under review; draft, open but not ready for review; merged;
 * closed without merging. Open: a newer hub may send other values.
 */
object TodoChangeState {
    const val OPEN = "open"
    const val DRAFT = "draft"
    const val MERGED = "merged"
    const val CLOSED = "closed"
    val ALL = listOf("open", "draft", "merged", "closed")
}

/**
 * Something a to-do's work produced, with how it stands: one chip of the paper's Results (proposal 3.5 row 9).
 */
@Serializable
data class TodoResult(
    /**
     * Unique among the to-do's results and stable while the hub keeps what it was read from; opaque to clients.
     */
    val id: String = "",
    val kind: String = "",
    /**
     * When it was produced.
     */
    val at: String = "",
    /**
     * What it came to, as written (a report's first line); absent for a change and a deploy, which clients name
     * themselves.
     */
    val text: String? = null,
    /**
     * Where it opens (the change, the first link a report named); absent when there is none.
     */
    val url: String? = null,
    /**
     * How a change stands now; absent while the hub has not looked, and for the other kinds.
     */
    val state: String? = null,
    /**
     * The run that produced it; absent when not known.
     */
    val run: TodoRunRef? = null,
)

/**
 * What changed on a to-do since the owner last looked: the paper's Since you looked (proposal 3.5 row 3).
 */
@Serializable
data class TodoRecap(
    /**
     * When the owner last looked (the to-do's seen_at).
     */
    val since: String = "",
    /**
     * The round of the first change since then, which a tap scrolls to.
     */
    val round: String = "",
    /**
     * How many entries of each type came since then, each of a run line's turns counted; only the types that have
     * any. The owner's own acts are left out, and so is what a round folds under one of them (the hub's relay of
     * their answer, the run their message started).
     */
    val counts: Map<String, Int> = emptyMap(),
)

/**
 * The top-level `todo` of a decision's push (category TODO_DECIDE, or TODO_DECIDE_OPEN, which no app gives actions;
 * docs/assistant/todos.md "Waiting for the owner") and of its WebSocket notify: what its Take Recommendation needs,
 * and from a manager that says how the push may answer it (#10465) the ask, the lock-screen rule and the options. A
 * push from an older manager carries the first four only and keeps TODO_DECIDE. The cases are in
 * spec/fixtures/todo-push.
 */
@Serializable
data class TodoDecidePush(
    /**
     * The to-do.
     */
    val id: TodoID = TodoID(""),
    /**
     * The round the decision waits in, as POST /api/v1/todos/{id}/accept takes it: an answer to an earlier round
     * takes nothing.
     */
    @SerialName("asked_at") val askedAt: String = "",
    /**
     * The label of the recommended option, which Take Recommendation takes.
     */
    val recommend: String = "",
    /**
     * The manager whose to-do it is, which every answer names in X-Persona-Manager.
     */
    val manager: String? = null,
    /**
     * The decision's ask in the to-do's view (OwnerAsk.id), which an answer from the notification names; absent from
     * an older manager.
     */
    val ask: String? = null,
    /**
     * What the notification may offer: answer, the category stays TODO_DECIDE and the options may be its actions;
     * open_only, the category is TODO_DECIDE_OPEN, with no action, and a tap opens the app. Absent from an older
     * manager: Take Recommendation only, as before.
     */
    val lockscreen: String? = null,
    /**
     * The decision's option labels, whole, the recommended first; only with lockscreen answer, and with
     * aps.mutable-content so the app's notification service extension can offer them. The hub drops both rather than
     * cut the alert under 500 characters when the push would not fit otherwise, never the category, lockscreen or
     * ask.
     */
    val options: List<String>? = null,
)

/**
 * What came of an answer to one of a to-do's asks (TodoAskAnswered): answered, the answer was taken (an option, a
 * fixed answer, the owner's words, a failed start started again, a conclusion acknowledged), though the ask may still
 * wait (explain_first leaves it waiting while the supervisor explains), so a client draws the reply's todo rather
 * than dropping the ask; declined, Don't handle was kept, with a receipt that undoes it; later, nothing was written
 * and the ask still waits (the client keeps Later for its app session); undone, a Don't handle was undone and the ask
 * waits again. Open: a newer hub may send other values.
 */
object TodoAskOutcome {
    const val ANSWERED = "answered"
    const val DECLINED = "declined"
    const val LATER = "later"
    const val UNDONE = "undone"
    val ALL = listOf("answered", "declined", "later", "undone")
}

/**
 * An answer that is an outcome rather than an option, a fixed answer or words (TodoAskAnswer.outcome): later, not
 * now: nothing is written; decline, Don't handle a decision, kept with a receipt; undo, that Don't handle undone,
 * with its receipt.
 */
object TodoAskAnswerOutcome {
    const val LATER = "later"
    const val DECLINE = "decline"
    const val UNDO = "undo"
    val ALL = listOf("later", "decline", "undo")
}

/**
 * The body of POST /api/v1/todos/{id}/asks/{ask}/answer (#10465), the answer to one of the to-do's own asks, named by
 * its view's ask id: at most one of option, response, text and outcome. None is the ask's one action: a failed start
 * started again, a conclusion that says the work cannot be done acknowledged. A run's ask is answered at its card,
 * not here. The operation's id is the X-Persona-Op-Id header, never the body.
 */
@Serializable
data class TodoAskAnswer(
    /**
     * The label of one of a decision's options, as its ask lists it; the recommended one takes the recommendation.
     */
    val option: String? = null,
    /**
     * A fixed answer to a decision that says the owner cannot answer it as asked: nothing is taken, and the to-do's
     * supervisor is told.
     */
    val response: String? = null,
    /**
     * The owner's own words answering a decision, at most 4000 characters (400 beyond): sent to the to-do's Agent as
     * they are, and kept with its decisions.
     */
    val text: String? = null,
    val outcome: String? = null,
    /**
     * With outcome undo: the receipt the decline answered.
     */
    val receipt: String? = null,
)

/**
 * The answer of POST /api/v1/todos/{id}/asks/{ask}/answer (#10465): what came of the answer, and the to-do as it
 * reads after it, so a client sets its row from one answer.
 */
@Serializable
data class TodoAskAnswered(
    /**
     * The ask answered, as the path named it.
     */
    val ask: String = "",
    val outcome: String = "",
    /**
     * none: no Agent could receive the answer, which is recorded and handed to the to-do's supervisor to pass on.
     * Absent when it reached the Agent or nothing had to be sent.
     */
    val delivered: String? = null,
    /**
     * With outcome declined: the receipt outcome undo takes.
     */
    val receipt: String? = null,
    /**
     * The to-do's row with its view, as GET /api/v1/todos/{id} answers it under todo (for a step's ask, the to-do
     * whose row lists it), read after the answer: it says whether the ask still waits, whatever the outcome; absent
     * when it could not be read.
     */
    val todo: JsonElement? = null,
)

/**
 * What GET /api/v1/todos/{id} answers beside `todo` (the list's hand-typed row, which clients read as their own row
 * type) from a manager that names todo_timeline (#10465): the paper's Conversation block, Results and Since you
 * looked (proposal 3.5 rows 3, 9 and 10), so the paper needs no second read. All four are absent from an older
 * manager, and when the manager could not read the to-do's history (the row still answers); recap and results also
 * when there is none.
 */
@Serializable
data class TodoItemDetail(
    /**
     * The rounds the paper shows, oldest first: the latest two that are not Background ones, the latest Background
     * ones making up the rest (spec/fixtures/todo-rounds/README.md R7); empty when the to-do has none. GET
     * /api/v1/todos/{id}/timeline has every round.
     */
    val rounds: List<TodoRound>? = null,
    /**
     * How many rounds the to-do's conversation has in all, the ones rounds leaves out included.
     */
    @SerialName("rounds_total") val roundsTotal: Int? = null,
    /**
     * What changed since the owner last looked; absent when they never did, or nothing but their own acts came since.
     */
    val recap: TodoRecap? = null,
    /**
     * What the to-do's work produced, newest first, at most 3; absent when nothing was.
     */
    val results: List<TodoResult>? = null,
)

/**
 * One field for each TodoListSection of TodoCounts.sections.
 */
@Serializable
data class TodoCountsSections(
    @SerialName("needs_you") val needsYou: Int = 0,
    @SerialName("can_wait") val canWait: Int = 0,
    val working: Int = 0,
    val waiting: Int = 0,
    val todo: Int = 0,
    @SerialName("just_finished") val justFinished: Int = 0,
    val someday: Int = 0,
    val done: Int = 0,
) {
    /**
     * The field of one TodoListSection: an unknown one reads 0.
     */
    operator fun get(key: TodoListSection): Int = when (key) {
        TodoListSection.NeedsYou -> needsYou
        TodoListSection.CanWait -> canWait
        TodoListSection.Working -> working
        TodoListSection.Waiting -> waiting
        TodoListSection.Todo -> todo
        TodoListSection.JustFinished -> justFinished
        TodoListSection.Someday -> someday
        TodoListSection.Done -> done
        is TodoListSection.Unknown -> 0
    }
}
